                'audio',
                'canvas',
                'circle',
                'clipPath',
                'defs',
                'desc',
                'discard',
                'ellipse',
                'feBlend',
                'feColorMatrix',
                'feComponentTransfer',
                'feComposite',
                'feConvolveMatrix',
                'feDiffuseLighting',
                'feDisplacementMap',
                'feDistantLight',
                'feDropShadow',
                'feFlood',
                'feFuncA',
                'feFuncB',
                'feFuncG',
                'feFuncR',
                'feGaussianBlur',
                'feImage',
                'feMerge',
                'feMergeNode',
                'feMorphology',
                'feOffset',
                'fePointLight',
                'feSpecularLighting',
                'feSpotLight',
                'feTile',
                'feTurbulence',
                'filter',
                'foreignObject',
                'g',
                'iframe',
                'image',
                'line',
                'linearGradient',
                'marker',
                'mask',
                'metadata',
                'mpath',
                'path',
                'pattern',
                'polygon',
                'polyline',
                'radialGradient',
                'rect',
                'script',
                'set',
                'stop',
                'style',
                'svg',
                'switch',
